const input=$json.body??$json;
const s=v=>String(v??'').trim();
const n=v=>Number(v);
const identity=input.identity??{};
const pkg=input.seller_offer_package??input.offer_package??{};
const counter=n(input.counteroffer_amount??input.counter_offer??input.seller_counter);
const mao=n(pkg.mao_ceiling??input.mao_ceiling??input.mao);
const target=n(pkg.target_offer??input.target_offer);
const minimum=n(pkg.minimum_acceptable??input.minimum_acceptable);
const opening=n(pkg.opening_offer??input.opening_offer);
const currentOffer=n(input.current_offer??input.last_offer??target);
const leadId=s(identity.lead_id??input.lead_id);
const propertyId=s(identity.property_id??input.property_id);
const dealId=s(identity.deal_id??input.deal_id);
const requestId=s(input.request_id??pkg.request_id);
const sellerIntent=s(input.seller_intent??input.response_intent??'counter').toLowerCase();
const underwritingApproved=['approved','ready','proceed','approved_with_conditions'].includes(s(input.underwriting_status).toLowerCase())||input.underwriting_approved===true;
const packageReady=s(pkg.status??input.package_status).toLowerCase()!=='blocked';
const missing=[];
if(!leadId)missing.push('lead_id');
if(!propertyId&&!dealId)missing.push('property_or_deal_id');
if(!Number.isFinite(counter)||counter<=0)missing.push('counteroffer_amount');
if(!Number.isFinite(mao)||mao<=0)missing.push('mao_ceiling');
if(!Number.isFinite(target)||target<=0)missing.push('target_offer');
if(!Number.isFinite(minimum)||minimum<0)missing.push('minimum_acceptable');
if(!underwritingApproved)missing.push('approved_underwriting');
if(!packageReady)missing.push('offer_package_ready');
const aboveMao=Number.isFinite(counter)&&Number.isFinite(mao)&&counter>mao;
const withinTarget=Number.isFinite(counter)&&Number.isFinite(target)&&counter<=target;
const withinPreferred=Number.isFinite(counter)&&Number.isFinite(minimum)&&counter>=minimum&&counter<=target;
const belowWalkAway=Number.isFinite(counter)&&Number.isFinite(minimum)&&counter<minimum;
let decision='human_review',reason='Insufficient evidence or approval state.';
if(missing.length)decision='blocked',reason='Required negotiation evidence is missing.';
else if(aboveMao)decision='walk_away',reason='Seller counteroffer exceeds the hard MAO ceiling.';
else if(sellerIntent==='accept')decision='accept',reason='Seller indicates acceptance of the current offer.';
else if(sellerIntent==='reject')decision='nurture',reason='Seller rejected the offer without an executable counter.';
else if(withinPreferred)decision='accept_or_finalize',reason='Counteroffer is inside the preferred negotiation band.';
else if(withinTarget)decision='accept_or_finalize',reason='Counteroffer is at or below target economics.';
else if(belowWalkAway)decision='counter_or_walk',reason='Counteroffer is below the minimum acceptable economics.';
else decision='counter',reason='Counteroffer is above target but remains within MAO.';
const counterRoom=Number.isFinite(mao)&&Number.isFinite(counter)?Math.max(0,mao-counter):0;
const recommendedResponse=decision==='accept'||decision==='accept_or_finalize'?'accept':decision==='counter'?'counter_with_ceiling':decision==='counter_or_walk'?'counter_at_minimum_or_walk':decision==='walk_away'?'decline_and_exit':decision==='nurture'?'close_loop_and_reengage_later':'human_review';
const nextState=decision==='accept'||decision==='accept_or_finalize'?'accepted':decision==='walk_away'?'rejected':decision==='nurture'?'stalled':decision==='blocked'?'human_review':'counter_evaluated';
const decisionId='counter-decision:'+s(dealId||propertyId||leadId||'unknown')+':'+s(requestId||'unknown')+':'+String(counter)+':v1';
const activity={
  activity_type:'counteroffer_decision',
  subject:'AI counteroffer decision '+decision,
  body:[
    'Counteroffer evaluated by Wholesaling OS.',
    'Seller counter: '+String(counter),
    'Current offer: '+String(currentOffer),
    'Target offer: '+String(target),
    'Minimum acceptable: '+String(minimum),
    'MAO ceiling: '+String(mao),
    'Decision: '+decision,
    'Reason: '+reason,
    'Next state: '+nextState
  ].join('\\n'),
  lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,
  external_id:decisionId,external_source:'wholesaling-os-counteroffer',
  metadata:{decision_id:decisionId,request_id:requestId||null,counteroffer_amount:counter,current_offer:currentOffer,target_offer:target,minimum_acceptable:minimum,mao_ceiling:mao,decision,reason,next_state:nextState,above_mao:aboveMao,counter_room:counterRoom,recommended_response:recommendedResponse}
};
return [{json:{
  ok:decision!=='blocked',
  status:decision==='blocked'?'blocked':'evaluated',
  decision_id:decisionId,
  request_id:requestId||null,
  identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},
  counteroffer:{amount:counter,above_mao:aboveMao,within_mao:!aboveMao,within_target:withinTarget,within_preferred_band:withinPreferred,below_walk_away:belowWalkAway},
  economics:{current_offer:currentOffer,target_offer:target,minimum_acceptable:minimum,mao_ceiling:mao,remaining_mao_room:counterRoom},
  decision:{action:decision,reason,recommended_response,next_state:nextState},
  guardrails:{never_accept_above_mao:true,never_counter_above_mao:true,underwriting_must_remain_approved:true,recheck_economics_on_every_counter:true},
  crm_activity:activity,
  missing_requirements:[...new Set(missing)],
  next_workflow:decision==='accept'||decision==='accept_or_finalize'?'wf-036-offer-lifecycle':decision==='counter'||decision==='counter_or_walk'?'wf-080-offer-negotiation-intelligence':decision==='blocked'?'human_review':'wf-099-seller-follow-up-timing'
}}];
